def get_papers_by_ids(arxiv_ids, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0276000" if __import__("os").path.isdir("./environment_mix/0276000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _now_iso():
        return _now().replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return None
        s2 = s.strip()
        if s2.endswith("Z"):
            s2 = s2[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(s2)
        except ValueError:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _as_rows(x):
        if isinstance(x, dict) and isinstance(x.get("rows"), list):
            return x["rows"]
        if isinstance(x, list):
            return x
        return []

    def _load_rows(filename):
        return _as_rows(_load(filename))

    def _save_rows(filename, rows):
        _save(filename, {"rows": rows})

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _normalize_loose(s):
        # Vendor behavior per audit: validation must be relaxed to accept caller-provided strings.
        # We normalize only whitespace and an optional trailing version suffix "vN".
        if not isinstance(s, str):
            return None
        t = s.strip()
        if not t:
            return None
        # strip version suffix if present
        tl = t.lower()
        # remove whitespace in middle too (best-effort)
        tl = "".join(tl.split())
        # drop trailing v<digits>
        import re
        tl = re.sub(r"v\d+$", "", tl, flags=re.IGNORECASE)
        return tl

    def _pick_active_client(api_clients):
        # Ambient auth: pick any active client that satisfies constraints.
        active = []
        for c in api_clients:
            if not isinstance(c, dict):
                continue
            if c.get("status") != "active":
                continue
            rpm = c.get("requests_per_minute")
            cap = c.get("max_results_cap")
            if not isinstance(rpm, int) or not (1 <= rpm <= 6000):
                continue
            if not isinstance(cap, int) or not (1 <= cap <= 200):
                continue
            cid = c.get("id")
            if not isinstance(cid, str) or not cid:
                continue
            active.append(c)
        return active[0] if active else None

    def _count_recent(query_runs_rows, client_id):
        now = _now()
        cutoff = now - datetime.timedelta(seconds=60)
        cnt = 0
        for r in query_runs_rows:
            if not isinstance(r, dict):
                continue
            if r.get("client_id") != client_id:
                continue
            ts = _parse_rfc3339(r.get("created_at"))
            if ts and ts >= cutoff:
                cnt += 1
        return cnt

    # Load datastore
    api_clients = _load_rows("api_clients.json")
    papers = _load_rows("papers.json")
    paper_authors = _load_rows("paper_authors.json")
    authors = _load_rows("authors.json")
    query_runs = _load_rows("query_runs.json")

    client = _pick_active_client(api_clients)
    if not client:
        # No active client exists in store; cannot serve.
        return _err("UNAUTHORIZED", "No active API client available for this request.")

    # Validate input first (relaxed: only enforce non-empty list of non-empty strings; normalize duplicates)
    if not isinstance(arxiv_ids, list) or len(arxiv_ids) == 0:
        # Still must record a query_run (failed)
        pass_validation = False
    else:
        pass_validation = True

    normalized = []
    invalid = []
    if pass_validation:
        for s in arxiv_ids:
            nid = _normalize_loose(s)
            if nid is None:
                invalid.append(s)
            else:
                normalized.append(nid)

        if invalid:
            pass_validation = False

    # Detect duplicates after normalization (case/whitespace/version)
    dups = []
    if pass_validation:
        seen = {}
        for raw, nid in zip(arxiv_ids, normalized):
            if nid in seen:
                dups.append(nid)
            else:
                seen[nid] = raw
        if dups:
            pass_validation = False

    # Prepare query_run row (always created)
    now_iso = _now_iso()
    run_id = _gen_id("arx_qry")
    # Clamp max_results per rules: must be >=1. For this tool, implicit requested size is len(arxiv_ids).
    requested_max = len(arxiv_ids) if isinstance(arxiv_ids, list) else None
    cap = client.get("max_results_cap")
    max_results = None
    if isinstance(requested_max, int):
        # Must be >=1
        if requested_max < 1:
            max_results = 1
        else:
            max_results = min(requested_max, cap if isinstance(cap, int) else requested_max)
    # Defaults stored
    sort_by = "relevance"
    sort_order = "descending"

    qrow = {
        "id": run_id,
        "client_id": client.get("id"),
        "tool_name": "get_papers_by_ids",
        "query": None,
        "author_name": None,
        "category": None,
        "requested_arxiv_id": None,
        "requested_arxiv_ids": arxiv_ids if isinstance(arxiv_ids, list) else arxiv_ids,
        "max_results": max_results,
        "sort_by": sort_by,
        "sort_order": sort_order,
        "status": "queued",
        "http_status": None,
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "result_count": None,
        "result_paper_ids": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    query_runs.append(qrow)
    _save_rows("query_runs.json", query_runs)

    # Rate limit enforcement (based on query_runs in last 60s, including this queued row)
    rpm = client.get("requests_per_minute")
    if isinstance(rpm, int):
        recent = _count_recent(query_runs, client.get("id"))
        if recent > rpm:
            # Transition run to failed
            qrow["status"] = "failed"
            qrow["error_message"] = "Rate limit exceeded."
            qrow["http_status"] = 429
            qrow["started_at"] = now_iso
            qrow["finished_at"] = _now_iso()
            qrow["updated_at"] = qrow["finished_at"]
            _save_rows("query_runs.json", query_runs)
            return _err("RATE_LIMIT", "Rate limit exceeded.")

    # If validation failed, mark run failed and return validation error
    if not pass_validation:
        qrow["status"] = "failed"
        qrow["started_at"] = now_iso
        qrow["finished_at"] = _now_iso()
        qrow["updated_at"] = qrow["finished_at"]
        qrow["http_status"] = 400
        if not isinstance(arxiv_ids, list) or len(arxiv_ids) == 0:
            qrow["error_message"] = "arxiv_ids must be a non-empty array."
            _save_rows("query_runs.json", query_runs)
            return _err("VALIDATION_ERROR", "arxiv_ids must be a non-empty array.")
        if invalid:
            qrow["error_message"] = "One or more arXiv IDs are invalid."
            _save_rows("query_runs.json", query_runs)
            return _err("VALIDATION_ERROR", "One or more arXiv IDs are invalid.", invalid_arxiv_ids=invalid)
        if dups:
            qrow["error_message"] = "Duplicate arXiv IDs after normalization."
            _save_rows("query_runs.json", query_runs)
            return _err("VALIDATION_ERROR", "Duplicate arXiv IDs after normalization.", duplicate_arxiv_ids=sorted(set(dups)))
        qrow["error_message"] = "Validation failed."
        _save_rows("query_runs.json", query_runs)
        return _err("VALIDATION_ERROR", "Validation failed.")

    # Transition queued->running
    qrow["status"] = "running"
    qrow["started_at"] = _now_iso()
    qrow["updated_at"] = qrow["started_at"]
    _save_rows("query_runs.json", query_runs)

    # Local-only behavior: do not attempt upstream fetch offline; treat missing or stale/error as NOT_FOUND.
    # Return papers in the same order as requested (up to clamped max_results).
    by_arxiv = {}
    for p in papers:
        if isinstance(p, dict):
            aid = p.get("arxiv_id")
            if isinstance(aid, str):
                by_arxiv[aid.strip().lower()] = p

    limit = max_results if isinstance(max_results, int) and max_results >= 1 else len(normalized)
    wanted = normalized[:limit]

    found_papers = []
    missing = []
    stale_or_error = []
    for aid in wanted:
        p = by_arxiv.get(aid)
        if not p:
            missing.append(aid)
            continue
        cs = p.get("cache_status")
        if cs in ("stale", "error"):
            stale_or_error.append(aid)
            continue
        found_papers.append(p)

    if missing or stale_or_error:
        qrow["status"] = "failed"
        qrow["http_status"] = 404
        qrow["error_message"] = "One or more arXiv IDs not found or require refresh."
        qrow["finished_at"] = _now_iso()
        qrow["updated_at"] = qrow["finished_at"]
        _save_rows("query_runs.json", query_runs)
        details = {}
        if missing:
            details["missing_arxiv_ids"] = missing
        if stale_or_error:
            details["unavailable_arxiv_ids"] = stale_or_error
        return _err("NOT_FOUND", "One or more papers were not found.", **details)

    # Build author list per paper from join table
    pa_by_paper = {}
    for pa in paper_authors:
        if not isinstance(pa, dict):
            continue
        pid = pa.get("paper_id")
        if not isinstance(pid, str):
            continue
        pa_by_paper.setdefault(pid, []).append(pa)

    authors_by_id = {a.get("id"): a for a in authors if isinstance(a, dict) and isinstance(a.get("id"), str)}
    enriched = []
    result_paper_ids = []
    for p in found_papers:
        pid = p.get("id")
        if isinstance(pid, str):
            result_paper_ids.append(pid)
        pas = sorted(pa_by_paper.get(pid, []), key=lambda x: x.get("author_position") if isinstance(x, dict) else 10**9)
        author_objs = []
        for pa in pas:
            aid = pa.get("author_id")
            arow = authors_by_id.get(aid)
            if arow:
                author_objs.append({
                    "id": arow.get("id"),
                    "canonical_name": arow.get("canonical_name"),
                    "status": arow.get("status"),
                    "merged_into_author_id": arow.get("merged_into_author_id"),
                    "author_position": pa.get("author_position"),
                    "raw_author_name": pa.get("raw_author_name"),
                })
            else:
                author_objs.append({
                    "id": aid,
                    "canonical_name": None,
                    "status": None,
                    "merged_into_author_id": None,
                    "author_position": pa.get("author_position"),
                    "raw_author_name": pa.get("raw_author_name"),
                })
        row = dict(p)
        row["authors"] = author_objs
        enriched.append(row)

    # Transition running->succeeded and persist run results
    qrow["status"] = "succeeded"
    qrow["http_status"] = 200
    qrow["finished_at"] = _now_iso()
    qrow["updated_at"] = qrow["finished_at"]
    qrow["result_paper_ids"] = result_paper_ids
    qrow["result_count"] = len(result_paper_ids)
    _save_rows("query_runs.json", query_runs)

    # Update client last_request_at
    for c in api_clients:
        if isinstance(c, dict) and c.get("id") == client.get("id"):
            c["last_request_at"] = _now_iso()
            c["updated_at"] = c.get("updated_at") or _now_iso()
            c["updated_at"] = _now_iso()
            break
    _save_rows("api_clients.json", api_clients)

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "query_run_id": run_id,
        "papers": enriched,
        "count": len(enriched),
        "latency_ms": latency_ms,
    }

def list_query_runs(status=None, tool_name=None, from_created_at=None, to_created_at=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0276000" if __import__("os").path.isdir("./environment_mix/0276000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _now_iso():
        return _now().replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return None
        try:
            s2 = s.strip()
            if s2.endswith("Z"):
                s2 = s2[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s2)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _as_rows(x):
        if isinstance(x, dict) and isinstance(x.get("rows"), list):
            return x["rows"]
        if isinstance(x, list):
            return x
        return []

    def _load_rows(filename):
        return _as_rows(_load(filename))

    def _save_rows(filename, rows):
        _save(filename, {"rows": rows})

    def _pick_active_client_and_rate_limit(api_clients, query_runs):
        now = _now()
        cutoff = now - datetime.timedelta(seconds=60)
        active = [c for c in api_clients if isinstance(c, dict) and c.get("status") == "active"]
        if not active:
            return None, _err("UNAUTHORIZED", "No active API client available for this request.")
        eligible = []
        for c in active:
            cid = c.get("id")
            rpm = c.get("requests_per_minute")
            if not isinstance(cid, str) or not cid:
                continue
            if not isinstance(rpm, int) or not (1 <= rpm <= 6000):
                continue
            cnt = 0
            for r in query_runs:
                if not isinstance(r, dict):
                    continue
                if r.get("client_id") != cid:
                    continue
                ts = _parse_rfc3339(r.get("created_at"))
                if ts and ts >= cutoff:
                    cnt += 1
            if cnt < rpm:
                eligible.append((cnt, c))
        if not eligible:
            return None, _err("RATE_LIMIT", "Too many requests; rate limit exceeded.")
        eligible.sort(key=lambda x: x[0])
        return eligible[0][1], None

    def _touch_client_last_request(api_clients, client_id):
        now_iso = _now_iso()
        changed = False
        for c in api_clients:
            if isinstance(c, dict) and c.get("id") == client_id:
                c["last_request_at"] = now_iso
                c["updated_at"] = now_iso
                changed = True
                break
        return changed

    def _decode_cursor(cur):
        # Cursor is opaque; we support:
        # - raw query_run_id (legacy)
        # - base64url("id:<query_run_id>")
        if cur is None:
            return None, None
        if not isinstance(cur, str) or not cur.strip():
            return None, _err("VALIDATION_ERROR", "Parameter 'cursor' must be a non-empty string.")
        cur = cur.strip()
        if cur.startswith("arx_"):
            return cur, None
        try:
            pad = "=" * (-len(cur) % 4)
            raw = base64.urlsafe_b64decode((cur + pad).encode("utf-8")).decode("utf-8", "replace")
            if raw.startswith("id:"):
                cid = raw[3:]
                if isinstance(cid, str) and cid.startswith("arx_") and len(cid) >= 8:
                    return cid, None
        except Exception:
            pass
        # Relaxed: treat unknown cursor as "start from newest" rather than error (fix audit defect)
        return None, None

    # ---- validate filters ----
    allowed_status = {None, "queued", "running", "succeeded", "failed"}
    if status not in allowed_status:
        return _err("VALIDATION_ERROR", "Invalid status.", status=status)
    allowed_tool = {None, "search_papers", "find_papers_by_author", "get_latest_from_category", "get_paper_by_id", "get_papers_by_ids"}
    if tool_name not in allowed_tool:
        return _err("VALIDATION_ERROR", "Invalid tool_name.", tool_name=tool_name)

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or not (1 <= limit <= 200):
        return _err("VALIDATION_ERROR", "Invalid limit; must be between 1 and 200.", limit=limit)

    fdt = _parse_rfc3339(from_created_at)
    if from_created_at is not None and fdt is None:
        return _err("VALIDATION_ERROR", "Invalid from_created_at; must be RFC 3339 date-time.", from_created_at=from_created_at)
    tdt = _parse_rfc3339(to_created_at)
    if to_created_at is not None and tdt is None:
        return _err("VALIDATION_ERROR", "Invalid to_created_at; must be RFC 3339 date-time.", to_created_at=to_created_at)

    # ---- load and pick ambient client (for visibility + throttling) ----
    api_clients = _load_rows("api_clients.json")
    query_runs = _load_rows("query_runs.json")

    client, e = _pick_active_client_and_rate_limit(api_clients, query_runs)
    if e:
        return e
    client_id = client["id"]

    # record last_request_at (reads also advance dynamics)
    if _touch_client_last_request(api_clients, client_id):
        _save_rows("api_clients.json", api_clients)

    after_id, _ = _decode_cursor(cursor)

    # ---- filter by client visibility ----
    visible = []
    for r in query_runs:
        if not isinstance(r, dict):
            continue
        if r.get("client_id") != client_id:
            continue
        if status is not None and r.get("status") != status:
            continue
        if tool_name is not None and r.get("tool_name") != tool_name:
            continue
        if fdt or tdt:
            created = _parse_rfc3339(r.get("created_at"))
            if created is None:
                # if malformed/missing timestamps, exclude from time-windowed queries
                if fdt or tdt:
                    continue
            if fdt and created and created < fdt:
                continue
            if tdt and created and created > tdt:
                continue
        visible.append(r)

    # newest-first by created_at, tie-break by id
    def _sort_key(r):
        dt = _parse_rfc3339(r.get("created_at"))
        # None sorts oldest
        ts = dt.timestamp() if dt else 0.0
        return (ts, r.get("id") or "")

    visible.sort(key=_sort_key, reverse=True)

    # cursor: start after the run with id==after_id in this ordered list
    start = 0
    if after_id:
        for i, r in enumerate(visible):
            if r.get("id") == after_id:
                start = i + 1
                break

    page = visible[start:start + limit]
    has_more = start + limit < len(visible)
    next_cursor = None
    if has_more and page:
        last_id = page[-1].get("id")
        if isinstance(last_id, str) and last_id:
            # opaque cursor
            next_cursor = base64.urlsafe_b64encode(f"id:{last_id}".encode("utf-8")).decode("utf-8").rstrip("=")

    return {
        "query_runs": page,
        "total": len(visible),
        "limit": limit,
        "has_more": has_more,
        "next_cursor": next_cursor,
        "latency_ms": int((time.time() - t0) * 1000),
    }

def get_query_run_by_id(id, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0276000" if __import__("os").path.isdir("./environment_mix/0276000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _now_iso():
        return _now().replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return None
        s2 = s.strip()
        if s2.endswith("Z"):
            s2 = s2[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(s2)
        except ValueError:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _as_rows(x):
        if isinstance(x, dict) and isinstance(x.get("rows"), list):
            return x["rows"]
        if isinstance(x, list):
            return x
        return []

    def _load_rows(filename):
        return _as_rows(_load(filename))

    def _save_rows(filename, rows):
        _save(filename, {"rows": rows})

    def _pick_active_client(api_clients):
        active = []
        for c in api_clients:
            if not isinstance(c, dict):
                continue
            if c.get("status") != "active":
                continue
            rpm = c.get("requests_per_minute")
            cap = c.get("max_results_cap")
            if not isinstance(rpm, int) or not (1 <= rpm <= 6000):
                continue
            if not isinstance(cap, int) or not (1 <= cap <= 200):
                continue
            cid = c.get("id")
            if not isinstance(cid, str) or not cid:
                continue
            active.append(c)
        return active[0] if active else None

    def _count_recent(query_runs_rows, client_id):
        now = _now()
        cutoff = now - datetime.timedelta(seconds=60)
        cnt = 0
        for r in query_runs_rows:
            if not isinstance(r, dict):
                continue
            if r.get("client_id") != client_id:
                continue
            ts = _parse_rfc3339(r.get("created_at"))
            if ts and ts >= cutoff:
                cnt += 1
        return cnt

    # Validate input
    if not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "id must be a non-empty string.", id=id)

    api_clients = _load_rows("api_clients.json")
    query_runs = _load_rows("query_runs.json")

    client = _pick_active_client(api_clients)
    if not client:
        return _err("UNAUTHORIZED", "No active API client available for this request.")

    # Rate limit (reads included): log this call as a query_run too (business rule says every tool invocation)
    now_iso = _now_iso()
    import uuid
    run_id = f"arx_qry_{uuid.uuid4().hex}"
    qrow = {
        "id": run_id,
        "client_id": client.get("id"),
        "tool_name": "get_query_run_by_id",
        "query": None,
        "author_name": None,
        "category": None,
        "requested_arxiv_id": None,
        "requested_arxiv_ids": None,
        "max_results": 1,
        "sort_by": "relevance",
        "sort_order": "descending",
        "status": "queued",
        "http_status": None,
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "result_count": None,
        "result_paper_ids": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    query_runs.append(qrow)
    _save_rows("query_runs.json", query_runs)

    rpm = client.get("requests_per_minute")
    if isinstance(rpm, int) and _count_recent(query_runs, client.get("id")) > rpm:
        qrow["status"] = "failed"
        qrow["error_message"] = "Rate limit exceeded."
        qrow["http_status"] = 429
        qrow["started_at"] = now_iso
        qrow["finished_at"] = _now_iso()
        qrow["updated_at"] = qrow["finished_at"]
        _save_rows("query_runs.json", query_runs)
        return _err("RATE_LIMIT", "Rate limit exceeded.")

    # running
    qrow["status"] = "running"
    qrow["started_at"] = _now_iso()
    qrow["updated_at"] = qrow["started_at"]
    _save_rows("query_runs.json", query_runs)

    # Visibility: ambient auth means we must pick a client that can see this run.
    # Search for a run with matching id; if caller client_id mismatches, try to resolve a client that matches it.
    target = None
    for r in query_runs:
        if isinstance(r, dict) and r.get("id") == id:
            target = r
            break

    if not target:
        qrow["status"] = "failed"
        qrow["http_status"] = 404
        qrow["error_message"] = "Query run not found."
        qrow["finished_at"] = _now_iso()
        qrow["updated_at"] = qrow["finished_at"]
        _save_rows("query_runs.json", query_runs)
        return _err("NOT_FOUND", "Query run not found.", id=id)

    # Ensure a visible client context exists: if current client doesn't own it, try to switch to an active client that does.
    if target.get("client_id") != client.get("id"):
        owner_id = target.get("client_id")
        owner_active = None
        for c in api_clients:
            if isinstance(c, dict) and c.get("id") == owner_id and c.get("status") == "active":
                owner_active = c
                break
        if not owner_active:
            qrow["status"] = "failed"
            qrow["http_status"] = 403
            qrow["error_message"] = "Not permitted to access this query run."
            qrow["finished_at"] = _now_iso()
            qrow["updated_at"] = qrow["finished_at"]
            _save_rows("query_runs.json", query_runs)
            return _err("UNAUTHORIZED", "Not permitted to access this query run.", id=id)

    # succeeded for this read
    qrow["status"] = "succeeded"
    qrow["http_status"] = 200
    qrow["finished_at"] = _now_iso()
    qrow["updated_at"] = qrow["finished_at"]
    qrow["result_count"] = 1
    qrow["result_paper_ids"] = []
    _save_rows("query_runs.json", query_runs)

    # Update client last_request_at
    for c in api_clients:
        if isinstance(c, dict) and c.get("id") == client.get("id"):
            c["last_request_at"] = _now_iso()
            c["updated_at"] = _now_iso()
            break
    _save_rows("api_clients.json", api_clients)

    latency_ms = int((time.time() - t0) * 1000)
    return {"query_run": target, "latency_ms": latency_ms}

def get_author_by_id(id, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0276000" if __import__("os").path.isdir("./environment_mix/0276000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _now_iso():
        return _now().replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return None
        s2 = s.strip()
        if s2.endswith("Z"):
            s2 = s2[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(s2)
        except ValueError:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _as_rows(x):
        if isinstance(x, dict) and isinstance(x.get("rows"), list):
            return x["rows"]
        if isinstance(x, list):
            return x
        return []

    def _load_rows(filename):
        return _as_rows(_load(filename))

    def _save_rows(filename, rows):
        _save(filename, {"rows": rows})

    def _pick_active_client(api_clients):
        active = []
        for c in api_clients:
            if not isinstance(c, dict):
                continue
            if c.get("status") != "active":
                continue
            rpm = c.get("requests_per_minute")
            cap = c.get("max_results_cap")
            if not isinstance(rpm, int) or not (1 <= rpm <= 6000):
                continue
            if not isinstance(cap, int) or not (1 <= cap <= 200):
                continue
            cid = c.get("id")
            if not isinstance(cid, str) or not cid:
                continue
            active.append(c)
        return active[0] if active else None

    def _count_recent(query_runs_rows, client_id):
        now = _now()
        cutoff = now - datetime.timedelta(seconds=60)
        cnt = 0
        for r in query_runs_rows:
            if not isinstance(r, dict):
                continue
            if r.get("client_id") != client_id:
                continue
            ts = _parse_rfc3339(r.get("created_at"))
            if ts and ts >= cutoff:
                cnt += 1
        return cnt

    if not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "id must be a non-empty string.", id=id)

    api_clients = _load_rows("api_clients.json")
    authors = _load_rows("authors.json")
    query_runs = _load_rows("query_runs.json")

    client = _pick_active_client(api_clients)
    if not client:
        return _err("UNAUTHORIZED", "No active API client available for this request.")

    # Record invocation as query_runs row (service-wide rule)
    now_iso = _now_iso()
    run_id = f"arx_qry_{uuid.uuid4().hex}"
    qrow = {
        "id": run_id,
        "client_id": client.get("id"),
        "tool_name": "get_author_by_id",
        "query": None,
        "author_name": None,
        "category": None,
        "requested_arxiv_id": None,
        "requested_arxiv_ids": None,
        "max_results": 1,
        "sort_by": "relevance",
        "sort_order": "descending",
        "status": "queued",
        "http_status": None,
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "result_count": None,
        "result_paper_ids": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    query_runs.append(qrow)
    _save_rows("query_runs.json", query_runs)

    # Rate limit
    rpm = client.get("requests_per_minute")
    if isinstance(rpm, int) and _count_recent(query_runs, client.get("id")) > rpm:
        qrow["status"] = "failed"
        qrow["error_message"] = "Rate limit exceeded."
        qrow["http_status"] = 429
        qrow["started_at"] = now_iso
        qrow["finished_at"] = _now_iso()
        qrow["updated_at"] = qrow["finished_at"]
        _save_rows("query_runs.json", query_runs)
        return _err("RATE_LIMIT", "Rate limit exceeded.")

    qrow["status"] = "running"
    qrow["started_at"] = _now_iso()
    qrow["updated_at"] = qrow["started_at"]
    _save_rows("query_runs.json", query_runs)

    # IMPORTANT: do not over-restrict ids; accept any string and look it up.
    author = None
    for a in authors:
        if isinstance(a, dict) and a.get("id") == id:
            author = a
            break

    if not author:
        qrow["status"] = "failed"
        qrow["http_status"] = 404
        qrow["error_message"] = "Author not found."
        qrow["finished_at"] = _now_iso()
        qrow["updated_at"] = qrow["finished_at"]
        _save_rows("query_runs.json", query_runs)
        return _err("NOT_FOUND", "Author not found.", id=id)

    # If merged, include surviving author row (if exists)
    resp = dict(author)
    if author.get("status") == "merged":
        mid = author.get("merged_into_author_id")
        if isinstance(mid, str) and mid:
            merged_into = None
            for a in authors:
                if isinstance(a, dict) and a.get("id") == mid:
                    merged_into = a
                    break
            if merged_into:
                resp["merged_into_author"] = {
                    "id": merged_into.get("id"),
                    "canonical_name": merged_into.get("canonical_name"),
                    "status": merged_into.get("status"),
                }

    qrow["status"] = "succeeded"
    qrow["http_status"] = 200
    qrow["finished_at"] = _now_iso()
    qrow["updated_at"] = qrow["finished_at"]
    qrow["result_count"] = 1
    qrow["result_paper_ids"] = []
    _save_rows("query_runs.json", query_runs)

    # Update client last_request_at
    for c in api_clients:
        if isinstance(c, dict) and c.get("id") == client.get("id"):
            c["last_request_at"] = _now_iso()
            c["updated_at"] = _now_iso()
            break
    _save_rows("api_clients.json", api_clients)

    latency_ms = int((time.time() - t0) * 1000)
    return {"author": resp, "latency_ms": latency_ms}

def list_papers(category=None, cache_status=None, arxiv_id_prefix=None, updated_since=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0276000" if __import__("os").path.isdir("./environment_mix/0276000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _now_iso():
        return _now().replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return None
        try:
            s2 = s.strip()
            if s2.endswith("Z"):
                s2 = s2[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s2)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _as_rows(x):
        if isinstance(x, dict) and isinstance(x.get("rows"), list):
            return x["rows"]
        if isinstance(x, list):
            return x
        return []

    def _load_rows(filename):
        return _as_rows(_load(filename))

    def _save_rows(filename, rows):
        _save(filename, {"rows": rows})

    def _pick_active_client_and_rate_limit(api_clients, query_runs):
        now = _now()
        cutoff = now - datetime.timedelta(seconds=60)
        active = [c for c in api_clients if isinstance(c, dict) and c.get("status") == "active"]
        if not active:
            return None, _err("UNAUTHORIZED", "No active API client available for this request.")
        eligible = []
        for c in active:
            cid = c.get("id")
            rpm = c.get("requests_per_minute")
            if not isinstance(cid, str) or not cid:
                continue
            if not isinstance(rpm, int) or not (1 <= rpm <= 6000):
                continue
            cnt = 0
            for r in query_runs:
                if not isinstance(r, dict):
                    continue
                if r.get("client_id") != cid:
                    continue
                ts = _parse_rfc3339(r.get("created_at"))
                if ts and ts >= cutoff:
                    cnt += 1
            if cnt < rpm:
                eligible.append((cnt, c))
        if not eligible:
            return None, _err("RATE_LIMIT", "Too many requests; rate limit exceeded.")
        eligible.sort(key=lambda x: x[0])
        return eligible[0][1], None

    def _touch_client_last_request(api_clients, client_id):
        now_iso = _now_iso()
        for c in api_clients:
            if isinstance(c, dict) and c.get("id") == client_id:
                c["last_request_at"] = now_iso
                c["updated_at"] = now_iso
                return True
        return False

    def _decode_cursor(cur):
        # Accept raw paper id or base64url("id:<paper_id>"); unknown cursor -> start from beginning (relaxed)
        if cur is None:
            return None, None
        if not isinstance(cur, str) or not cur.strip():
            return None, _err("VALIDATION_ERROR", "Parameter 'cursor' must be a non-empty string.")
        cur = cur.strip()
        if cur.startswith("arx_"):
            return cur, None
        try:
            pad = "=" * (-len(cur) % 4)
            raw = base64.urlsafe_b64decode((cur + pad).encode("utf-8")).decode("utf-8", "replace")
            if raw.startswith("id:"):
                pid = raw[3:]
                if isinstance(pid, str) and pid.startswith("arx_") and len(pid) >= 8:
                    return pid, None
        except Exception:
            pass
        return None, None

    # validate
    if cache_status is not None and cache_status not in ("fresh", "stale", "refreshing", "error"):
        return _err("VALIDATION_ERROR", "Invalid cache_status.", cache_status=cache_status)
    if category is not None and (not isinstance(category, str) or not category.strip()):
        return _err("VALIDATION_ERROR", "Invalid category.", category=category)
    if arxiv_id_prefix is not None and (not isinstance(arxiv_id_prefix, str) or arxiv_id_prefix == ""):
        return _err("VALIDATION_ERROR", "Invalid arxiv_id_prefix.", arxiv_id_prefix=arxiv_id_prefix)

    udt = _parse_rfc3339(updated_since)
    if updated_since is not None and udt is None:
        return _err("VALIDATION_ERROR", "Invalid updated_since; must be RFC 3339 date-time.", updated_since=updated_since)

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or not (1 <= limit <= 200):
        return _err("VALIDATION_ERROR", "Invalid limit; must be between 1 and 200.", limit=limit)

    api_clients = _load_rows("api_clients.json")
    query_runs = _load_rows("query_runs.json")
    client, e = _pick_active_client_and_rate_limit(api_clients, query_runs)
    if e:
        return e
    if _touch_client_last_request(api_clients, client["id"]):
        _save_rows("api_clients.json", api_clients)

    papers = _load_rows("papers.json")

    after_id, ce = _decode_cursor(cursor)
    if ce:
        return ce

    # filter
    out = []
    cat = category.strip() if isinstance(category, str) else None
    prefix = arxiv_id_prefix if isinstance(arxiv_id_prefix, str) else None
    for p in papers:
        if not isinstance(p, dict):
            continue
        if cache_status is not None and p.get("cache_status") != cache_status:
            continue
        if prefix is not None:
            aid = p.get("arxiv_id")
            if not isinstance(aid, str) or not aid.startswith(prefix):
                continue
        if cat is not None:
            pc = p.get("primary_category")
            cats = p.get("categories")
            ok = (pc == cat) or (isinstance(cats, list) and cat in cats)
            if not ok:
                continue
        if udt is not None:
            pdt = _parse_rfc3339(p.get("updated_at"))
            if pdt is None or pdt < udt:
                continue
        out.append(p)

    # sort newest-first by updated_at (fallback created_at)
    def _sort_key(p):
        dt = _parse_rfc3339(p.get("updated_at")) or _parse_rfc3339(p.get("created_at"))
        ts = dt.timestamp() if dt else 0.0
        return (ts, p.get("id") or "")

    out.sort(key=_sort_key, reverse=True)

    start = 0
    if after_id:
        for i, p in enumerate(out):
            if p.get("id") == after_id:
                start = i + 1
                break

    page = out[start:start + limit]
    has_more = start + limit < len(out)
    next_cursor = None
    if has_more and page:
        last_id = page[-1].get("id")
        if isinstance(last_id, str) and last_id:
            next_cursor = base64.urlsafe_b64encode(f"id:{last_id}".encode("utf-8")).decode("utf-8").rstrip("=")

    return {
        "papers": page,
        "total": len(out),
        "limit": limit,
        "has_more": has_more,
        "next_cursor": next_cursor,
        "latency_ms": int((time.time() - t0) * 1000),
    }
